from authoring import *
p=[obs(18,1,'爆光场中景，黑袍者小剪影在左后，青在右前闭眼用前臂护脸，中心左侧白光占主要画面，亮粒与弧光向外。',['黑袍来者','青','白色爆光','亮粒','岩壁'],['青前臂挡脸','弧光向外扩开'],['来者左后，青右前，白光中央偏左'],[['青','GAAH!!'],['春子','什么情况？！']],['うわっ！！','何これ？！'],ROCK,P('指间轻响刚落，青还看着前方。',['白光骤亮，青立刻抬前臂护住脸，闭眼偏头，发束与衣角被气流推向右侧；黑袍剪影仍在左后站定。'],'突发变化让青护脸，来者却早有准备。','青护住脸，白光峰值开始减弱。'),'手指动作触发源格白光爆开，保持二人远近。','以已见弧光亮粒与护脸为界，不补碎墙或身体被击飞。','Action'),obs(18,2,'青正面头肩近景居画面中央偏左，睁圆眼张口，前臂与张开的手横过下方近层，脸侧汗点，岩壁在后。',['青','前臂','张开的手','岩壁'],['青睁圆眼张口','前臂挡在身前'],['青脸在中央偏左，前臂下方近层'],[['青','……!!!!','inner']],['……！'],ROCK,P('青前臂还挡着脸，眼睛闭着。',['爆光减弱，她慢慢睁眼，前臂降到身前，手指仍张着；惊讶让她张口，却一时说不出话。'],'从本能护脸转成看清变化后的震惊。','前臂在身前，青睁圆眼望着前方。'),'白光退后看清青的反应，保持护臂未完全放下。','省略号与叹号为无声震惊，不补对白或新身体接触。','Reaction'),obs(19,1,'中全景，黑袍者背面上身在下方中央，巨大圆形白色通道在中后层，外缘旋纹清楚，岩壁周围小亮粒密集。',['黑袍来者','圆形白色通道','亮粒','岩壁'],['通道外缘旋动','亮粒围绕通道'],['来者下方近层，圆形通道后方中央'],[['黑袍来者','去吧.'],['黑袍来者','这是一条通往北方地下城的通道.']],['行け。','北のダンジョンへ通じる道だ。'],ROCK,P('白光峰值退去，来者仍在前方。',['宽白能量向中心收成圆形通道，外缘旋纹由急到稳，亮粒随流线转动；来者从容说明目的地。'],'刚才的突发变化被解释为可用的北行通道。','圆形通道稳定，来者站在下方近层。'),'爆光与震惊之后揭示完整通道形态。','只呈现源图圆形发光通道，不补里面未画出的北方风景。','Action')]
write('observations',18,p[:2]);write('observations',19,p[2:])
d=[F(p[0],4,'指间轻响落下，中央偏左白光骤然爆开，尖细弧光与亮粒短促向外扩。青立刻抬前臂护住脸，闭眼偏头，发束和衣角被气流推向右侧；黑袍者的剪影留在左后，光峰很短，随即退亮，粒子分散变小。',['突发受惊，短促叫出。','画外惊讶，急问。'],scene='洞窟入口',light='冷白爆光短促照亮青的左侧脸缘与蓝色衣装，岩壁凸面瞬亮，光峰之后迅速减弱，黑袍剪影保持完整。',sound='白光启动一声低闷轰鸣，气流急掠，衣料拍动，亮粒伴细密滋响，轰鸣随后下降。'),F(p[1],3,'白光减弱后，青慢慢睁开眼，挡脸的前臂降到身前，张开的手仍绷着。她震惊地张口，脸侧留一点汗，眼神定在前方，一时没有真的说出话。',['无声震惊，不实际朗读。'],scene='洞窟入口',light='左前冷白残光照亮青的脸与手，蓝色衣装仍保留块面阴影，岩壁反光从强变柔。',sound='能量低鸣降到较轻底响，衣袖落下时短擦声。'),F(p[2],5,'宽白能量向中心收成圆形通道，外缘旋纹从急转变得匀稳。大小亮粒沿圆周流线绕行，近处较快、远处较慢，少数粒子变小熄灭；黑袍者背影留在下方，从容示意进去并说明目的地，通道内仍是一片亮白。',['简短、直接。','从容说明，目的地清楚。'],scene='洞窟入口',light='通道冷白光映亮黑袍外缘和附近凸石，袍内块面仍深暗，能量稳定后岩壁亮度也稳定。',sound='圆形通道低频嗡鸣持续，外缘流动带细密气流，少量亮粒细响时有起落。')]
